static int failf(const char *fmt, ...) {
    va_list ap;
    printf("GRAMMAR-BREAK ");
    va_start(ap, fmt);
    vprintf(fmt, ap);
    va_end(ap);
    putchar('\n');
    return 1;
}

static const uint8_t ZERO76[76] = {0};

static long bit_at(const uint8_t *pay, long paylen, long i) {
    if (i < 0 || (i >> 3) >= paylen) {
        printf("GRAMMAR-BREAK bit-range\n");
        exit(1);
    }
    return (long)((pay[i >> 3] >> (i & 7)) & 1);
}

static long grp_list(const uint8_t *pay, long paylen,
                     const long *idx, long k) {
    long v = 0;
    for (long j = 0; j < k; j++)
        v |= bit_at(pay, paylen, idx[j]) << j;
    return v;
}

static long grp_range(const uint8_t *pay, long paylen, long a,
                      long b) {
    long v = 0;
    for (long i = a; i < b; i++)
        v |= bit_at(pay, paylen, i) << (i - a);
    return v;
}

static void hex_of(const uint8_t *p, long n, char *out) {
    static const char H[] = "0123456789abcdef";
    for (long i = 0; i < n; i++) {
        out[2 * i] = H[p[i] >> 4];
        out[2 * i + 1] = H[p[i] & 15];
    }
    out[2 * n] = 0;
}

static long lmin(long a, long b) { return a < b ? a : b; }

